import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"Мок-сервер","description":"","frontmatter":{},"headers":[],"relativePath":"ru/advanced/mock-server.md","filePath":"ru/advanced/mock-server.md","lastUpdated":1784904021000}'),n={name:"ru/advanced/mock-server.md"};function e(h,s,o,p,r,d){return i(),t("div",null,[...s[0]||(s[0]=[l(`<h1 id="мок-сервер" tabindex="-1">Мок-сервер <a class="header-anchor" href="#мок-сервер" aria-label="Permalink to &quot;Мок-сервер&quot;">​</a></h1><h2 id="обзор" tabindex="-1">Обзор <a class="header-anchor" href="#обзор" aria-label="Permalink to &quot;Обзор&quot;">​</a></h2><p>Мок-сервер генерирует фиктивные ответы API на основе ваших OpenAPI-схем. Он позволяет тестировать интеграцию API без выполнения реальных HTTP-вызовов. Это полезно для разработки, тестирования LLM-агентов и демонстраций.</p><p>Мок-сервер — это <strong>отдельный бинарник</strong> — <code>swag2mcp-mock</code>. Он не входит в основной бинарник <code>swag2mcp</code> и должен быть установлен отдельно.</p><h2 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Вариант 1: Скачать из GitHub Releases</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ищите swag2mcp-mock_&amp;lt;version&amp;gt;_&amp;lt;os&amp;gt;_&amp;lt;arch&amp;gt;.tar.gz</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Вариант 2: Установить через Go</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com/mmadfox/swag2mcp/cmd/swag2mcp-mock@latest</span></span></code></pre></div><h2 id="конфигурация" tabindex="-1">Конфигурация <a class="header-anchor" href="#конфигурация" aria-label="Permalink to &quot;Конфигурация&quot;">​</a></h2><p>Включите мок-сервер в вашем конфиге:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">mock_enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">mock_auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  oauth2_port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9090</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  digest_port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9091</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  hmac_port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9092</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">specs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Dad Joke API</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://icanhazdadjoke.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    collections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://raw.githubusercontent.com/mmadfox/swag2mcp/main/specs/dadjoke.yaml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        base_mock_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1:9090&quot;</span></span></code></pre></div><h2 id="параметры" tabindex="-1">Параметры <a class="header-anchor" href="#параметры" aria-label="Permalink to &quot;Параметры&quot;">​</a></h2><h3 id="mock-enabled" tabindex="-1">mock_enabled <a class="header-anchor" href="#mock-enabled" aria-label="Permalink to &quot;mock_enabled&quot;">​</a></h3><ul><li><strong>Тип:</strong> <code>bool</code></li><li><strong>По умолчанию:</strong> <code>false</code></li><li><strong>Эффект:</strong> При <code>true</code> каждая активная коллекция должна иметь установленный <code>base_mock_url</code>. Мок-сервер запускает HTTP-серверы для каждой коллекции.</li></ul><h3 id="mock-auth" tabindex="-1">mock_auth <a class="header-anchor" href="#mock-auth" aria-label="Permalink to &quot;mock_auth&quot;">​</a></h3><p>Порты для мок-серверов аутентификации. Они симулируют конечные точки OAuth2, Digest и HMAC, чтобы вы могли тестировать API с аутентификацией без реальных учётных данных.</p><table tabindex="0"><thead><tr><th>Поле</th><th>По умолчанию</th><th>Описание</th></tr></thead><tbody><tr><td><code>oauth2_port</code></td><td><code>9090</code></td><td>Порт для мок-сервера OAuth2-токенов</td></tr><tr><td><code>digest_port</code></td><td><code>9091</code></td><td>Порт для мок-сервера Digest-аутентификации</td></tr><tr><td><code>hmac_port</code></td><td><code>9092</code></td><td>Порт для мок-сервера HMAC-аутентификации</td></tr></tbody></table><h3 id="base-mock-url-на-коллекцию" tabindex="-1">base_mock_url (на коллекцию) <a class="header-anchor" href="#base-mock-url-на-коллекцию" aria-label="Permalink to &quot;base_mock_url (на коллекцию)&quot;">​</a></h3><ul><li><strong>Тип:</strong> <code>string</code></li><li><strong>Обязательный:</strong> Да (когда <code>mock_enabled: true</code>)</li><li><strong>Формат:</strong> <code>host:port</code> (например, <code>localhost:8080</code>, <code>127.0.0.1:9000</code>)</li><li><strong>Эффект:</strong> Каждая коллекция получает свой собственный HTTP-сервер на этом адресе. Сервер отвечает на все эндпоинты, определённые в спецификации, случайно сгенерированными данными.</li></ul><h2 id="запуск-мок-сервера" tabindex="-1">Запуск мок-сервера <a class="header-anchor" href="#запуск-мок-сервера" aria-label="Permalink to &quot;Запуск мок-сервера&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Запуск с конфигом по умолчанию</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp-mock</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mockserver</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Запуск с TLS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp-mock</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mockserver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tls</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Запуск с пользовательским TLS-сертификатом</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp-mock</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mockserver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tls-cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tls-key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key.pem</span></span></code></pre></div><h3 id="tls-флаги" tabindex="-1">TLS-флаги <a class="header-anchor" href="#tls-флаги" aria-label="Permalink to &quot;TLS-флаги&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Флаг</th><th>Описание</th></tr></thead><tbody><tr><td><code>--tls</code></td><td>Включить TLS с самоподписанным сертификатом</td></tr><tr><td><code>--tls-cert</code></td><td>Путь к файлу TLS-сертификата</td></tr><tr><td><code>--tls-key</code></td><td>Путь к файлу TLS-ключа</td></tr></tbody></table><p>Если <code>--tls</code> установлен без <code>--tls-cert</code> и <code>--tls-key</code>, самоподписанный сертификат генерируется автоматически для <code>localhost</code>.</p><h2 id="что-делает-мок-сервер" tabindex="-1">Что делает мок-сервер <a class="header-anchor" href="#что-делает-мок-сервер" aria-label="Permalink to &quot;Что делает мок-сервер&quot;">​</a></h2><p>При запуске мок-сервер:</p><ol><li><strong>Парсит все файлы спецификаций</strong> — читает OpenAPI/Swagger-спецификацию каждой коллекции</li><li><strong>Регистрирует обработчики</strong> — создаёт HTTP-обработчик для каждого пути и метода, определённых в спецификации</li><li><strong>Генерирует фиктивные данные</strong> — отвечает случайно сгенерированными данными, соответствующими схеме ответа (правильные типы, форматы и структура)</li><li><strong>Запускает серверы аутентификации</strong> — симулирует конечные точки OAuth2, Digest и HMAC для тестирования</li></ol><h3 id="тестирование-мока" tabindex="-1">Тестирование мока <a class="header-anchor" href="#тестирование-мока" aria-label="Permalink to &quot;Тестирование мока&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># В одном терминале:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp-mock</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mockserver</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># В другом терминале:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/pets</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → [{&quot;id&quot;:1,&quot;name&quot;:&quot;Pet_name&quot;,&quot;status&quot;:&quot;available&quot;}]</span></span></code></pre></div><h2 id="как-генерируются-фиктивные-данные" tabindex="-1">Как генерируются фиктивные данные <a class="header-anchor" href="#как-генерируются-фиктивные-данные" aria-label="Permalink to &quot;Как генерируются фиктивные данные&quot;">​</a></h2><p>Мок-сервер генерирует реалистичные фиктивные данные на основе OpenAPI-схемы:</p><ul><li><strong>Строки</strong> — случайные слова, предложения или значения, специфичные для формата (email, URL, UUID, дата, телефон и т.д.)</li><li><strong>Числа</strong> — случайные целые числа и числа с плавающей точкой в указанном диапазоне</li><li><strong>Булевы</strong> — случайные true/false</li><li><strong>Массивы</strong> — от 1 до 3 случайных элементов</li><li><strong>Объекты</strong> — все свойства заполнены случайными значениями</li><li><strong>Перечисления</strong> — случайное значение из списка перечисления</li><li><strong>Nullable-поля</strong> — иногда возвращает <code>null</code> (~10% вероятность)</li></ul><h2 id="варианты-использования" tabindex="-1">Варианты использования <a class="header-anchor" href="#варианты-использования" aria-label="Permalink to &quot;Варианты использования&quot;">​</a></h2><ul><li><strong>Разработка</strong> — тестируйте интеграцию без доступа к реальному API</li><li><strong>Тестирование LLM-агентов</strong> — проверьте, что LLM может обнаруживать, проверять и вызывать эндпоинты</li><li><strong>Демонстрации</strong> — покажите swag2mcp в работе без настройки реальных API</li><li><strong>Нагрузочное тестирование</strong> — тестируйте MCP-сервер под нагрузкой без обращения к реальным API</li></ul><h2 id="важные-замечания" tabindex="-1">Важные замечания <a class="header-anchor" href="#важные-замечания" aria-label="Permalink to &quot;Важные замечания&quot;">​</a></h2><ul><li><strong>Отдельный бинарник</strong> — <code>swag2mcp-mock</code> не входит в основной бинарник <code>swag2mcp</code>. Устанавливайте его отдельно.</li><li><strong>Каждая коллекция получает свой порт</strong> — настраивайте <code>base_mock_url</code> для каждой коллекции</li><li><strong>Мок-серверы аутентификации глобальны</strong> — серверы OAuth2, Digest и HMAC работают на настроенных портах независимо от количества коллекций</li><li><strong>Ошибки парсинга спецификаций не фатальны</strong> — если спецификацию коллекции не удалось распарсить, она пропускается с предупреждением</li><li><strong>Самоподписанный TLS</strong> — при использовании <code>--tls</code> без сертификатов генерируется самоподписанный сертификат только для localhost</li></ul>`,34)])])}const g=a(n,[["render",e]]);export{c as __pageData,g as default};
